class Resources extends HTMLElement{constructor(){super(),this.resourseBlocks=this.querySelectorAll("[data-resource-block]");var e=Array.from(this.resourseBlocks).map(e=>e.dataset.resourceBlock);this.resourseTypes=[...new Set(e)],this.init()}init(){customer&&this.setUrl()}async getRewardsToken(){return(await(await fetch("https://obagi-api.westus.cloudapp.azure.com/api/premier-points/token?id="+customer.id)).json())?.token}setUrl(){this.resourseTypes.forEach(e=>{const t=this.querySelectorAll(`[data-resource-block=${e}] a[href]`);"rewards"===e&&this.getRewardsToken().then(e=>{let s=e?"https://practice.obagi.com/sso-login?token="+e:"https://practice.obagi.com/";t.forEach(e=>e.setAttribute("href",s))})})}}customElements.define("resource-blocks",Resources);